const lang = $('Input Wrapper').first().json.job_post_language.language || 'de';
const isEn = lang === 'en';

const copy = isEn
  ? {
      scoreLabel: 'Score', dimension: 'Dimension', score: 'Score', max: 'Max',
      technical: 'Technical', requirements: 'Requirements', roleFit: 'Role Fit',
      location: 'Location', strategic: 'Strategic',
      thresholdLabel: {
        pass:    '✅ Match — application package generated',
        caution: '⚠️ Borderline — package with caution note',
        fail:    '❌ Not recommended — gap analysis'
      }
    }
  : {
      scoreLabel: 'Score', dimension: 'Dimension', score: 'Score', max: 'Max',
      technical: 'Technisch', requirements: 'Anforderungen', roleFit: 'Rollenfit',
      location: 'Standort', strategic: 'Strategisch',
      thresholdLabel: {
        pass:    '✅ Match — Bewerbungspaket erstellt',
        caution: '⚠️ Grenzfall — Paket mit Hinweis',
        fail:    '❌ Nicht empfohlen — Gap-Analyse'
      }
    };

let bodyText = '';
let cvDiff = '';
let cvMarkdown = '';

// Pass/caution branch — Anschreiben comes from Anscheiben node
try {
  bodyText = $('Anschreiben').first().json.text || '';
} catch(e) {}

// Fail branch — Gap Analysis
if (!bodyText) {
  try {
    bodyText = $('Gap Analysis').first().json.text || '';
  } catch(e) {}
}

// CV diff and clean markdown from Diff Engine
try {
  cvDiff     = $('Diff Engine').first().json.cv_diff     || '';
  cvMarkdown = $('Diff Engine').first().json.cv_markdown  || '';
} catch(e) {}

const data = $('Call Analysis Scoring').first().json;
const filled = Math.round(data.score / 10);
const empty  = 10 - filled;
const bar    = '█'.repeat(filled) + '░'.repeat(empty);

const thresholdLabel = copy.thresholdLabel[data.threshold] || '';

const header = `## ${data.role_title}
**${data.company}** · ${copy.scoreLabel}: ${data.score}/100 \`${bar}\` ${thresholdLabel}
| ${copy.dimension} | ${copy.score} | ${copy.max} |
|---|---|---|
| ${copy.technical}     | ${data.dimensions.technical}     | 40 |
| ${copy.requirements}  | ${data.dimensions.requirements}  | 25 |
| ${copy.roleFit}       | ${data.dimensions.role_fit}      | 20 |
| ${copy.location}      | ${data.dimensions.location}      | 10 |
| ${copy.strategic}     | ${data.dimensions.strategic}     | 5  |
---
`;

return [{
  json: {
    output:      header + bodyText,
    cv_diff:     cvDiff,
    cv_markdown: cvMarkdown,
    body_text: bodyText,
  }
}];

