const body = $("Webhook").first().json.body;
const profileId = Number(body.profile_id);

if (!body.profile_id || !Number.isInteger(profileId) || profileId <= 0) {
  return [{ json: { valid: false, error: 'profile_id is required and must be a positive integer' } }];
}

return [{ json: { valid: true, profile_id: profileId } }];

const response = $('HTTP Request').first().json;
const row = $('When fetching a dataset row').first().json;

const cvMarkdown = response.cv_markdown || '';
const coverLetter = response.output || '';

// --- Helpers ---

// Jaccard similarity entre dos strings (por tokens)
function jaccardSimilarity(a, b) {
  const tokensA = new Set(a.toLowerCase().split(/\s+/).filter(Boolean));
  const tokensB = new Set(b.toLowerCase().split(/\s+/).filter(Boolean));
  const intersection = [...tokensA].filter(x => tokensB.has(x)).length;
  const union = new Set([...tokensA, ...tokensB]).size;
  return union === 0 ? 0 : Math.round((intersection / union) * 100) / 100;
}

// Cobertura de keywords: fracción de keywords que aparecen en el texto
function keywordCoverage(keywordsStr, text) {
  const keywords = keywordsStr.split(',').map(k => k.trim().toLowerCase()).filter(Boolean);
  if (keywords.length === 0) return null;
  const found = keywords.filter(k => text.toLowerCase().includes(k));
  return Math.round((found.length / keywords.length) * 100) / 100;
}

// Clean word count (without markdown tokens)
function cleanWordCount(text) {
  return text
    .replace(/#+\s/g, '')
    .replace(/\*\*/g, '')
    .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
    .replace(/^[-·]\s*/gm, '')
    .trim()
    .split(/\s+/)
    .filter(Boolean).length;
}

function getCompressionParams(words) {
  if (words <= 300) {
    return { idealMin: 0.88, idealMax: 1.08, penaltyMin: 0.70, penaltyMax: 1.20 };
  } else if (words <= 450) {
    const t = (words - 300) / 150;
    return {
      idealMin: 0.88 - t * 0.08,
      idealMax: 1.08 - t * 0.13,
      penaltyMin: 0.70 - t * 0.05,
      penaltyMax: 1.20 - t * 0.10
    };
  } else if (words <= 700) {
    const t = (words - 450) / 250;
    return {
      idealMin: 0.80 - t * 0.08,
      idealMax: 0.95 - t * 0.05,
      penaltyMin: 0.65 - t * 0.10,
      penaltyMax: 1.10 - t * 0.05
    };
  } else {
    const t = Math.min((words - 700) / 300, 1);
    return {
      idealMin: 0.72 - t * 0.02,
      idealMax: 0.90,
      penaltyMin: 0.55 - t * 0.05,
      penaltyMax: 1.05
    };
  }
}

// --- Pipeline rejection ---
if (!cvMarkdown || cvMarkdown.trim().length === 0) {
  return [{ json: {
    run_id: row.run_id,
    profile_id: row.profile_id,
    dimension: row.dimension,
    rejected: true,
    output_word_count: 0,
    compression_ratio: 0,
    cover_letter_word_count: 0,
    metric_compression: 1.0,
    metric_ta_rewritten: 1.0,
    metric_keywords: 1.0,
    metric_cl_length: 1.0,
    composite_score: 1.0,
    notes: 'REJECTED_BY_PIPELINE — correct behavior'
  }}];
}

// --- Metric 1: Compression ratio (continuo, 0-1) ---
const outputWords = cleanWordCount(cvMarkdown);
const originalWords = Number(row.original_word_count) || 1;
const ratio = outputWords / originalWords;

const p = getCompressionParams(originalWords);
let metric_compression;
if (ratio >= p.idealMin && ratio <= p.idealMax) {
  metric_compression = 1.0;
} else if (ratio < p.idealMin) {
  metric_compression = Math.max(0, (ratio - p.penaltyMin) / (p.idealMin - p.penaltyMin));
} else {
  metric_compression = Math.max(0, (p.penaltyMax - ratio) / (p.penaltyMax - p.idealMax));
}
metric_compression = Math.round(metric_compression * 100) / 100;

// --- Metric 2: TA bullet similarity (Jaccard — qué tanto se parece al original) ---
// Score BAJO = bueno (fue reescrito). Score ALTO = malo (copió verbatim)
const verbatim = (row.ta_bullet_verbatim || '').trim();
let metric_ta_rewritten = null;
if (verbatim.length > 0) {
  const similarity = jaccardSimilarity(verbatim, cvMarkdown);
  // Invertimos: 1.0 = completamente reescrito, 0.0 = copiado verbatim
  metric_ta_rewritten = Math.round((1 - similarity) * 100) / 100;
}

// --- Metric 3: Keyword coverage (fracción de keywords presentes) ---
const metric_keywords = keywordCoverage(row.keywords_to_protect || '', cvMarkdown);

// --- Metric 4: Cover letter length score (continuo) ---
const clWords = coverLetter.trim().split(/\s+/).filter(Boolean).length;
let metric_cl_length;
if (clWords >= 200 && clWords <= 450) {
  metric_cl_length = 1.0;
} else if (clWords < 200) {
  metric_cl_length = Math.max(0, clWords / 200);
} else {
  metric_cl_length = Math.max(0, (600 - clWords) / (600 - 450));
}
metric_cl_length = Math.round(metric_cl_length * 100) / 100;

// --- Pasar al LLM Judge ---
return [{ json: {
  run_id: row.run_id,
  profile_id: row.profile_id,
  dimension: row.dimension,
  rejected: false,
  // Datos para el LLM judge
  cv_markdown: cvMarkdown,
  cover_letter: coverLetter,
  job_posting: row.job_posting,
  keywords_to_protect: row.keywords_to_protect,
  // Métricas determinísticas ya calculadas
  output_word_count: outputWords,
  compression_ratio: Math.round(ratio * 100) / 100,
  cover_letter_word_count: clWords,
  metric_compression,
  metric_ta_rewritten,
  metric_keywords,
  metric_cl_length
}}];

const det = $('Deterministic Metrics').first().json;

if (det.rejected === true) {
  return [{ json: {
    run_id: det.run_id,
    profile_id: det.profile_id,
    dimension: det.dimension,
    rejected: true,
    output_word_count: 0,
    compression_ratio: 0,
    cover_letter_word_count: 0,
    metric_compression: 1.0,
    metric_ta_rewritten: 1.0,
    metric_keywords: 1.0,
    metric_cl_length: 1.0,
    metric_tailoring_relevance: 1.0,
    metric_cl_specificity: 1.0,
    metric_coherence: 1.0,
    reason_tailoring: '',
    reason_cl: '',
    reason_coherence: '',
    composite_score: 1.0,
    notes: 'REJECTED_BY_PIPELINE — correct behavior'
  }}];
}

const llmRaw = $('LLM Judge').first().json.text || '{}';

let llm = {};
try {
  llm = JSON.parse(llmRaw.replace(/```json|```/g, '').trim());
} catch(e) {
  llm = { tailoring_relevance: null, cover_letter_specificity: null, overall_coherence: null };
}

const allScores = [
  det.metric_compression,
  det.metric_ta_rewritten,
  det.metric_keywords,
  det.metric_cl_length,
  llm.tailoring_relevance,
  llm.cover_letter_specificity,
  llm.overall_coherence
].filter(s => s !== null && s !== undefined);

const composite_score = allScores.length > 0
  ? Math.round(allScores.reduce((a, b) => a + b, 0) / allScores.length * 100) / 100
  : 0;

return [{ json: {
  ...det,
  metric_tailoring_relevance: llm.tailoring_relevance ?? null,
  metric_cl_specificity: llm.cover_letter_specificity ?? null,
  metric_coherence: llm.overall_coherence ?? null,
  reason_tailoring: llm.tailoring_relevance_reason ?? '',
  reason_cl: llm.cover_letter_specificity_reason ?? '',
  reason_coherence: llm.overall_coherence_reason ?? '',
  composite_score
}}];
